export type PlayerIconName = keyof typeof GLYPHS;

export const playerIconNames = Object.keys(GLYPHS) as PlayerIconName[];

export type PlayerIconProps = { name: PlayerIconName; size?: number; color?: string };

export function PlayerIcon({ name, size = 24, color = '#fff' }: PlayerIconProps) {
  const glyph: Glyph = GLYPHS[name];
  return (
    <Svg width={size} height={size} viewBox={`0 0 ${glyph.box} ${glyph.box}`} fill="none">
      {glyph.stroke ? (
        <Path d={glyph.stroke} stroke={color} strokeWidth={glyph.strokeWidth} strokeLinecap="round" fill="none" />
      ) : null}
      {glyph.fill ? <Path d={glyph.fill} fill={color} fillRule={glyph.evenodd ? 'evenodd' : 'nonzero'} /> : null}
    </Svg>
  );
}
